 FROM samples s LEFT JOIN core.awards a ON stream='awards' AND a.ca_notice_id=s.id
 LEFT JOIN core.notices n ON stream='tenders' AND n.c_notice_id=s.id
)
SELECT row_to_json(x) FROM (
 SELECT year,stream,count(*) FILTER(WHERE stored_no IS NOT NULL) stored,
 count(*) FILTER(WHERE stored_no IS NOT NULL AND (stored_no<>notice_no OR stored_type<>notice_type)) mismatched_identity,
 jsonb_agg(jsonb_build_object('id',id,'source',notice_no,'stored',stored_no,'source_type',notice_type,'stored_type',stored_type))
 FILTER(WHERE stored_no IS NOT NULL AND (stored_no<>notice_no OR stored_type<>notice_type)) examples
 FROM checked GROUP BY 1,2 ORDER BY 1,2
)x;COMMIT;
